//Demonstrate the use of map method in ReactJS to display array.

function Map() {
  const fruits = ["Apple", "Banana", "Mango", "Orange"];

        {/* 
        Apple  → key=0
        Banana → key=1
        Mango  → key=2
        Orange → key=3 */}


  return (
    <div>

      <h2>Fruit List</h2>

{/* 
        () => ()  implicit return means it returns data automatically 
        () => {} explicit return means we need to return manually 
         */}
     
      <ul style={{listStyleType : 'disc',  paddingLeft: "40px"}}>

        {fruits.map(
            (fruit, index) => {
            return(
                <li key={index}>{fruit}</li>
            )   
        })}
       

        {/* {fruits.map((fruit, index) => (
            
                <li key={index}>{fruit}</li>  
            ))} */}
    
      </ul>

        <h2>Without index</h2>

      <ul style={{listStyleType:'disc', paddingLeft:'40px'}}>
         
        {fruits.map((fruit) => (
            <li>{fruit}</li>
        ))}

      </ul>
    </div>
  );
}


//  table using map

function Table() {

    const stu = [
    { id: 1, sname: 'abc', spi: 8.9 },
    { id: 2, sname: 'def', spi: 8.2 },
    { id: 3, sname: 'ghi', spi: 8.7 },
    { id: 4, sname: 'jkl', spi: 8.5 },
    { id: 5, sname: 'mnp', spi: 8.3 }
    ];

    const data = stu.map((temp) => {   // store in new var bcs map method returns new list and original remains same
        return (
            <tr key={temp.id}>
                <td>{temp.id}</td>
                <td>{temp.sname}</td>
                <td>{temp.spi}</td>
            </tr>
        )
    })

    return (
        <table border={2} style={{margin : 10}}>
            <thead>
                <tr >
                    <th>ID</th>
                    <th>Student Name</th>
                    <th>SPI</th>
                </tr>
            </thead>
           
            <tbody>
                {data}
            </tbody>

        </table>

    )
}

// card using map

function Card() {

    const product = [
    { pname: 'pencil', price: 5, company: 'apsara', img : 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQHIexA37xt9ldH_BVMXZPYD713ZmEqTXDcPQ&s' },
    { pname: 'pen', price: 10, company: 's.s pinlong',img : 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSHCLm1Z_ospfHkvkNpxi28GfWkClRTSmceYw&s' },
    { pname: 'book', price: 50, company: 'doms', img : 'data:image/jpeg;base64,' },
    { pname: 'color', price: 40, company: 'camel', img : 'data:image/jpeg;base64,' }];

    const data = product.map((temp2) => {
        return (
            <>
            <div class="col-4 mt-5 ">
                <div class="card bg-dark text-light" style={{width: 300}}>
                <img src = {temp2.img} style={{height : 200 , width : 200 , margin : 30 , marginLeft : 50}}></img>
                    <div class="card-body text-center">
                        <h5 class="card-title">{temp2.pname}</h5><hr/>
                        <h6 class=" mb-2 card-text">Company : {temp2.company}</h6>
                        <p class="card-text">Price : {temp2.price}</p>
                    </div>
                </div>
                </div>
            </>
        )
    })

    return (
        <div class="container" >
            <div class="row">
                {data}
            </div>
        </div>
    )
}

export {Map, Table, Card };
